<?php
declare(strict_types=1);
final class CatalogQualityService{public function __construct(private PDO $db){}public function scan():array{$issues=[];$checks=['sin_marca'=>'SELECT id,name FROM perfumes WHERE deleted_at IS NULL AND brand_id IS NULL','sin_categoria'=>'SELECT id,name FROM perfumes WHERE deleted_at IS NULL AND category_id IS NULL','sin_descripcion'=>"SELECT id,name FROM perfumes WHERE deleted_at IS NULL AND COALESCE(short_description,'')=''",'disponibilidad_pendiente'=>"SELECT id,name FROM perfumes WHERE deleted_at IS NULL AND availability_status='pendiente'",'sin_imagen'=>"SELECT id,name FROM perfumes WHERE deleted_at IS NULL AND (COALESCE(main_image,'')='' OR main_image IS NULL)",'slug_invalido'=>"SELECT id,name FROM perfumes WHERE slug NOT REGEXP '^[a-z0-9]+(-[a-z0-9]+)*$'"];foreach($checks as $type=>$sql){$rows=$this->db->query($sql)->fetchAll();$issues[$type]=count($rows);foreach($rows as $row){$s=$this->db->prepare('INSERT INTO catalog_quality_reviews(entity_type,entity_id,issue_type,details_json) VALUES(?,?,?,?)');$s->execute(['perfume',(int)$row['id'],$type,json_encode(['name'=>$row['name']],JSON_UNESCAPED_UNICODE)]);}}return $issues;}}
